(window.DOM_TESTS=window.DOM_TESTS||{})["lecture-6"]={"lecture":"lecture-6","chapters":["cerebral","coronary","pulmonary","splanchnic","skin","fetal"],"questions":[{"id":"lt-lecture-6:775594a3","chapter":"cerebral","section":"2-where-does-the-blood-come-from","type":"mechanism","stem":"The two vertebral arteries join to supply the posterior brain through which main arterial pathway?","options":{"A":"The external carotid pathway.","B":"The basilar artery pathway.","C":"The anterior communicating artery.","D":"The superior sagittal sinus."},"answer":"B","why":"The two vertebral arteries unite as the basilar artery, which supplies the posterior circulation.","not":{"A":"The external carotid primarily serves extracranial tissues.","C":"The anterior communicating artery links anterior cerebral arteries.","D":"The sagittal sinus drains venous blood rather than supplying arteries."}},{"id":"lt-lecture-6:b05f5c68","chapter":"cerebral","section":"2-where-does-the-blood-come-from","type":"application","stem":"A patient has a large infarct affecting the lateral surface of one cerebral hemisphere. Which arterial territory is most likely?","options":{"A":"Anterior cerebral artery.","B":"Posterior cerebral artery.","C":"Middle cerebral artery.","D":"Anterior communicating artery."},"answer":"C","why":"The middle cerebral artery supplies most of the lateral cerebral hemisphere, making it the relevant territory.","not":{"A":"The anterior cerebral artery mainly supplies medial frontal and parietal surfaces.","B":"The posterior cerebral artery predominantly supplies occipital and inferior temporal territories.","D":"The communicating artery is a collateral link rather than the main lateral supply."}},{"id":"lt-lecture-6:51bea8b8","chapter":"cerebral","section":"2-where-does-the-blood-come-from","type":"mechanism","stem":"Why can a cerebral arterial branch occlusion cause a local infarct despite the Circle of Willis?","options":{"A":"Small distal territories may have limited effective collateral flow.","B":"Every cerebral artery has a complete set of parallel branches.","C":"Cerebral veins normally replace arterial inflow after blockage.","D":"The basilar artery can supply every distal cortical branch directly."},"answer":"A","why":"The Circle of Willis provides proximal connections, but distal cerebral arterial territories have limited functional anastomoses.","not":{"B":"Distal vessels are not completely interconnected.","C":"Veins drain blood and cannot substitute for oxygenated arterial supply.","D":"Basilar inflow does not directly replace all distal arterial territories."}},{"id":"lt-lecture-6:a9e94243","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"anatomy","stem":"Which meningeal layer closely follows the sulci and contours of the cerebral surface?","options":{"A":"The dura mater.","B":"Arachnoid mater.","C":"Subdural membrane.","D":"The pia mater."},"answer":"D","why":"Pia mater adheres directly to the brain and follows its surface contours, unlike the bridging arachnoid.","not":{"A":"Dura mater is the tough outer covering.","B":"Arachnoid lies more superficially and bridges sulci.","C":"The potential subdural space is not a meningeal layer."}},{"id":"lt-lecture-6:df7bb760","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"mechanism","stem":"CSF leaves the lateral ventricles to enter the third ventricle through which passage?","options":{"A":"The foramina of Luschka.","B":"The foramen of Monro.","C":"The cerebral aqueduct.","D":"The median aperture of Magendie."},"answer":"B","why":"The interventricular foramina (Monro) connect the lateral ventricles to the third ventricle. The passage is upstream of the third ventricle, so obstruction can enlarge the lateral ventricles.","not":{"A":"Luschka exits the fourth ventricle laterally.","C":"The aqueduct connects third and fourth ventricles.","D":"Magendie is the median fourth-ventricle outlet."}},{"id":"lt-lecture-6:f8c2317e","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"mechanism","stem":"A narrowed cerebral aqueduct obstructs CSF passage. Which change would be expected upstream?","options":{"A":"Enlargement limited to the fourth ventricle.","B":"Immediate excess flow into the subarachnoid space.","C":"Expansion of lateral and third ventricles.","D":"Isolated enlargement of the central canal."},"answer":"C","why":"The aqueduct lies between the third and fourth ventricles, so upstream lateral and third ventricles enlarge.","not":{"A":"The fourth ventricle lies downstream of the block.","B":"Obstruction decreases onward drainage into subarachnoid space.","D":"The central canal is downstream and not the primary dilated compartment."}},{"id":"lt-lecture-6:0671f2ff","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"mechanism","stem":"Once CSF reaches the subarachnoid space, through which route is it mainly absorbed?","options":{"A":"Through arachnoid villi into dural venous sinuses.","B":"Through pia mater directly into cerebral arteries.","C":"Through the foramen of Monro into the veins.","D":"Through the cerebral aqueduct into the aorta."},"answer":"A","why":"Arachnoid villi and granulations return CSF to the dural venous sinuses. Its drainage capacity is a key determinant of CSF balance.","not":{"B":"Pia does not discharge CSF into cerebral arteries.","C":"Monro connects ventricles and is not the absorption site.","D":"The aqueduct joins ventricles, not the systemic arterial circuit."}},{"id":"lt-lecture-6:d321e00d","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"calculation","stem":"The CSF volume is about 150 mL and production is 550 mL/day. Approximately how many complete turnovers occur per day?","options":{"A":"About 1.","B":"About 2.","C":"About 6.","D":"About 4."},"answer":"D","why":"Dividing daily production by total CSF volume gives 550/150 ≈ 3.7 turnovers each day.","not":{"A":"One turnover would represent only about 150 mL/day.","B":"Two turnovers would require about 300 mL/day.","C":"Six turnovers would correspond to around 900 mL/day."}},{"id":"lt-lecture-6:7780d626","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"conceptual","stem":"How does CSF substantially reduce the effective weight of the brain?","options":{"A":"It increases the brain's intrinsic density.","B":"It provides buoyant support against gravity.","C":"It directly reduces the brain's oxygen consumption.","D":"It reduces blood volume to near zero."},"answer":"B","why":"Immersion provides buoyancy, reducing the brain's effective supported weight from roughly 1400–1500 g to around 50 g.","not":{"A":"The tissue density does not increase to create buoyancy.","C":"Lower oxygen consumption does not explain mechanical support.","D":"Brain blood volume remains substantial."}},{"id":"lt-lecture-6:cac8444a","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"comparison","stem":"A patient has hydrocephalus due to impaired absorption by arachnoid villi without an obstructed ventricular pathway. What type is this?","options":{"A":"Noncommunicating hydrocephalus.","B":"Obstructive aqueductal hydrocephalus.","C":"Communicating hydrocephalus.","D":"Isolated ventricular haemorrhage."},"answer":"C","why":"Communicating hydrocephalus occurs when CSF reaches subarachnoid space but reabsorption is impaired. The ventricular pathway remains open, so the defect is in absorption rather than transit.","not":{"A":"Noncommunicating hydrocephalus results from blocked ventricular drainage.","B":"Aqueductal stenosis is a specific obstruction.","D":"Haemorrhage may contribute to hydrocephalus but is not the classification described."}},{"id":"lt-lecture-6:09aac42d","chapter":"cerebral","section":"5-the-coverings-the-ventricles-and-csf","type":"application","stem":"A patient develops headache that is worse upright after lumbar CSF sampling. Which mechanism is most likely?","options":{"A":"Persistent CSF leakage lowers intracranial CSF pressure.","B":"The sample immediately increases blood–brain barrier permeability.","C":"Lumbar puncture increases CSF production several-fold.","D":"The procedure obstructs both foramina of Monro."},"answer":"A","why":"Leakage from the dural puncture can reduce CSF pressure and cause a characteristic postural headache.","not":{"B":"BBB disruption is not the usual cause of post-lumbar-puncture headache.","C":"Production does not normally surge to cause this symptom.","D":"The foramina are far from the lumbar puncture site."}},{"id":"lt-lecture-6:9b93d768","chapter":"cerebral","section":"6-the-blood-brain-barrier","type":"anatomy","stem":"Which structure forms the key physical restriction to paracellular movement across the blood–brain barrier?","options":{"A":"Astrocytic end-feet alone.","B":"The choroid plexus epithelium.","C":"Loose junctions of cerebral venules.","D":"Endothelial tight junctions."},"answer":"D","why":"Tight junctions in cerebral capillary endothelium restrict movement between cells; astrocytes support barrier function.","not":{"A":"Astrocytes help maintain the barrier but are not the main sealed endothelial layer.","B":"The choroid plexus forms a separate blood–CSF barrier.","C":"Loose venular junctions would not account for selective restriction."}},{"id":"lt-lecture-6:08ceca32","chapter":"cerebral","section":"6-the-blood-brain-barrier","type":"mechanism","stem":"How does glucose enter the brain despite the restrictive blood–brain barrier?","options":{"A":"By free movement through tight junctions.","B":"Through a specific endothelial transporter.","C":"Through bulk passage of plasma proteins.","D":"Through insulin-triggered endothelial pores."},"answer":"B","why":"Glucose crosses the BBB through transporters such as GLUT1; its entry does not require insulin.","not":{"A":"Endothelial tight junctions block most paracellular solutes.","C":"Protein leakage is limited by the barrier.","D":"Cerebral glucose transport is largely insulin independent."}},{"id":"lt-lecture-6:a4023cd5","chapter":"cerebral","section":"6-the-blood-brain-barrier","type":"comparison","stem":"Which substance passes relatively readily across the intact blood–brain barrier without a carrier?","options":{"A":"Plasma albumin.","B":"A protein-bound drug.","C":"Carbon dioxide.","D":"A large immunoglobulin."},"answer":"C","why":"Small diffusible gases such as oxygen and carbon dioxide cross the endothelial membrane relatively easily.","not":{"A":"Albumin is a large protein with restricted passage.","B":"Protein binding reduces free diffusion across the BBB.","D":"Large immunoglobulins do not easily cross intact endothelial tight junctions."}},{"id":"lt-lecture-6:8b42d905","chapter":"cerebral","section":"3-how-does-the-brain-keep-its-blood-flow-steady","type":"mechanism","stem":"A highly active cortical region accumulates carbon dioxide and hydrogen ions. What is the expected local vascular response?","options":{"A":"Local arterioles constrict, reducing perfusion.","B":"Local arterioles dilate, increasing perfusion.","C":"Capillaries close while arteriolar tone stays fixed.","D":"Venules constrict without an arteriolar response."},"answer":"B","why":"Increased local CO₂ and H⁺ cause cerebral arteriolar vasodilation, improving blood delivery to metabolically active tissue.","not":{"A":"Constriction would reduce flow to the region that needs more oxygen.","C":"Capillary closure would worsen rather than correct the local supply-demand mismatch.","D":"Isolated venular constriction does not explain metabolic regulation of cerebral arteriolar inflow."}},{"id":"lt-lecture-6:487089f0","chapter":"cerebral","section":"4-a-rigid-box-intracranial-pressure-and-perfusion","type":"calculation","stem":"Intracranial pressure rises while mean arterial pressure remains constant. What happens to cerebral perfusion pressure?","options":{"A":"It rises by the same amount.","B":"It remains fixed by cardiac output.","C":"It becomes equal to venous return.","D":"It falls with increased ICP."},"answer":"D","why":"Cerebral perfusion pressure is approximately mean arterial pressure minus intracranial pressure; raising ICP reduces it.","not":{"A":"Increased ICP subtracts from the arterial driving pressure.","B":"Autoregulation does not make the pressure difference mathematically constant.","C":"Venous return and cerebral perfusion pressure are different quantities."}},{"id":"lt-lecture-6:f910345b","chapter":"cerebral","section":"4-a-rigid-box-intracranial-pressure-and-perfusion","type":"mechanism","stem":"A severe rise in intracranial pressure produces systemic hypertension with reflex bradycardia. What is this response?","options":{"A":"Bainbridge reflex.","B":"Cushing reflex.","C":"Atrial stretch reflex.","D":"Lung hypoxia reflex."},"answer":"B","why":"The Cushing response reflects brainstem ischaemia driving systemic hypertension, with baroreflex-mediated bradycardia. Brain perfusion is threatened as raised intracranial pressure compresses cerebral vessels.","not":{"A":"Bainbridge responds to increased atrial filling.","C":"Atrial stretch does not explain raised ICP-driven hypertension.","D":"Pulmonary hypoxic vasoconstriction is a local lung response."}},{"id":"lt-lecture-6:3a004764","chapter":"cerebral","section":"7-stroke","type":"comparison","stem":"A cerebral vessel ruptures and blood enters brain tissue. Which type of cerebrovascular event is present?","options":{"A":"Thrombotic ischaemia.","B":"Embolic ischaemia.","C":"Haemorrhagic stroke.","D":"Cerebral hypoglycaemia."},"answer":"C","why":"Haemorrhagic stroke results from rupture of a vessel, whereas ischaemic stroke results from interrupted arterial supply.","not":{"A":"Thrombosis obstructs an artery instead of rupturing it.","B":"Embolism blocks flow rather than directly representing vessel rupture.","D":"Hypoglycaemia causes global dysfunction rather than vessel rupture."}},{"id":"lt-lecture-6:6be9c061","chapter":"cerebral","section":"1-why-the-brain-can-t-wait-for-blood","type":"application","stem":"Why can a brief complete interruption of cerebral blood flow cause unconsciousness within seconds?","options":{"A":"The brain has very limited stores of oxygen and fuel.","B":"The brain stores enough ATP for several minutes of activity.","C":"The cerebral circulation can switch immediately to venous oxygen.","D":"The brainstem normally stops all electrical activity first."},"answer":"A","why":"Neural activity depends on continuous perfusion because energy and oxygen reserves are small; the lecture cites roughly 10 seconds.","not":{"B":"Adequate stored energy does not sustain function for many minutes.","C":"Venous blood cannot replace arterial oxygen delivery.","D":"The lecture describes cortical vulnerability, with brainstem structures relatively more resistant."}},{"id":"lt-lecture-6:1a513218","chapter":"coronary","section":"2-trace-coronary-inflow-and-venous-drainage","type":"anatomy","stem":"Which location gives rise to the right and left coronary arteries?","options":{"A":"The pulmonary arterial bifurcation.","B":"The superior vena cava junction.","C":"The aortic sinuses near the valve cusps.","D":"The coronary sinus opening in the atrium."},"answer":"C","why":"The coronary ostia arise from the aortic sinuses immediately above the aortic valve. These are distinct from the coronary sinus, which drains myocardial venous blood.","not":{"A":"The pulmonary trunk conducts deoxygenated blood to the lungs.","B":"The superior vena cava returns systemic venous blood.","D":"The coronary sinus drains venous blood into the right atrium."}},{"id":"lt-lecture-6:c78c6eb8","chapter":"coronary","section":"2-trace-coronary-inflow-and-venous-drainage","type":"anatomy","stem":"Most blood draining the myocardium returns to the right atrium through which structure?","options":{"A":"The coronary sinus.","B":"The pulmonary veins.","C":"The superior vena cava alone.","D":"The aortic sinuses."},"answer":"A","why":"The coronary sinus collects most cardiac venous drainage and empties into the right atrium.","not":{"B":"Pulmonary veins return oxygenated blood from lungs to left atrium.","C":"The superior vena cava is not the primary collection route for cardiac veins.","D":"Aortic sinuses supply arterial coronary inflow."}},{"id":"lt-lecture-6:65215335","chapter":"coronary","section":"3-why-is-left-ventricular-coronary-perfusion-greatest-during-diastole","type":"mechanism","stem":"Why is perfusion of the left ventricular myocardium predominantly diastolic?","options":{"A":"The coronary ostia close during ventricular systole.","B":"Aortic flow stops entirely during ventricular diastole.","C":"The left ventricle receives no blood during relaxation.","D":"Ventricular contraction compresses intramural vessels."},"answer":"D","why":"High left ventricular wall tension during systole squeezes intramyocardial coronary vessels; relaxation permits better flow.","not":{"A":"Coronary ostia remain open through the cardiac cycle.","B":"Aortic pressure persists during diastole and drives coronary flow.","C":"Coronary flow increases during relaxation rather than disappearing."}},{"id":"lt-lecture-6:8beeed17","chapter":"coronary","section":"4-how-does-coronary-flow-match-changing-myocardial-work","type":"mechanism","stem":"A heart begins working harder during exercise. Which local change most directly helps increase its coronary blood flow?","options":{"A":"A sustained rise in arteriolar alpha-adrenergic constriction.","B":"Accumulation of adenosine and other vasodilating metabolites.","C":"Decreased myocardial metabolism with higher local oxygen.","D":"Closure of capillary networks in the ventricular wall."},"answer":"B","why":"Higher cardiac work increases oxygen use and metabolites including adenosine, promoting coronary vasodilation and active hyperaemia.","not":{"A":"Alpha-mediated constriction is not the main response matching flow to greater work.","C":"Lower metabolism would not explain exercise hyperaemia.","D":"Capillary closure would oppose increased oxygen delivery."}},{"id":"lt-lecture-6:f76dfbdb","chapter":"coronary","section":"4-how-does-coronary-flow-match-changing-myocardial-work","type":"comparison","stem":"What effect does activating alpha-adrenoceptors have on vessels supplying the myocardium?","options":{"A":"Coronary vasoconstriction.","B":"Metabolic vasodilation.","C":"Capillary oxygen extraction.","D":"Greater cardiac muscle inotropy."},"answer":"A","why":"The lecture identifies coronary alpha-receptor stimulation as directly vasoconstricting, distinct from metabolic vasodilation. Local metabolic signals can still override this direct constrictor tendency during increased myocardial work.","not":{"B":"Metabolic dilation is driven largely by myocardial activity and metabolites.","C":"Oxygen extraction is a tissue process, not a direct receptor effect.","D":"Increased contractility is associated with cardiac beta-adrenergic stimulation."}},{"id":"lt-lecture-6:002e7a54","chapter":"coronary","section":"4-how-does-coronary-flow-match-changing-myocardial-work","type":"mechanism","stem":"Cardiac beta-adrenergic stimulation raises coronary flow overall mainly through which chain?","options":{"A":"Less contraction → less oxygen use → greater vascular tone.","B":"More contraction → less ATP use → less adenosine.","C":"More work → metabolites → arteriolar dilation.","D":"Direct beta stimulation → closure of coronary arterioles."},"answer":"C","why":"Sympathetic stimulation raises cardiac work and oxygen demand; local metabolites then increase coronary perfusion despite competing vasomotor effects.","not":{"A":"Reduced contraction is not the expected beta-mediated cardiac response.","B":"Greater work increases, not reduces, ATP consumption.","D":"Coronary flow is not increased by closing the arterioles."}},{"id":"lt-lecture-6:e61af466","chapter":"coronary","section":"5-why-can-tachycardia-cause-ischaemia","type":"application","stem":"Why is a patient with significant coronary narrowing more vulnerable to angina when heart rate rises sharply?","options":{"A":"The P wave disappears and blocks blood flow.","B":"Myocardial oxygen consumption falls below baseline.","C":"The coronary sinus develops arterial hypertension.","D":"Shorter diastole and higher myocardial demand."},"answer":"D","why":"Tachycardia increases cardiac oxygen demand and shortens diastole, reducing the time available for left ventricular coronary perfusion.","not":{"A":"An absent P wave is not the explanation of demand-related angina.","B":"Myocardial work and oxygen consumption generally rise with tachycardia.","C":"The primary limitation is coronary supply through stenosed arteries during shortened diastole."}},{"id":"lt-lecture-6:ace25bc3","chapter":"coronary","section":"6-coronary-flow-reserve-angina-and-myocardial-infarction","type":"application","stem":"A patient with coronary atheroma is comfortable at rest but develops exertional chest pain. Which explanation fits best?","options":{"A":"The coronary artery becomes completely normal during exercise.","B":"Restricted coronary flow reserve cannot meet increased demand.","C":"Exercise lowers heart oxygen requirements below resting levels.","D":"Coronary flow stops at rest but rest pain is absent."},"answer":"B","why":"A narrowed vessel may deliver adequate resting flow but cannot dilate enough to meet exercise demand, causing reversible ischaemia.","not":{"A":"Plaque does not disappear with exertion.","C":"Exercise raises myocardial work and oxygen requirements.","D":"Resting coronary flow may be sufficient despite reduced reserve."}},{"id":"lt-lecture-6:1243cda1","chapter":"coronary","section":"6-coronary-flow-reserve-angina-and-myocardial-infarction","type":"comparison","stem":"What most clearly differentiates myocardial infarction from brief stable angina?","options":{"A":"Prolonged ischaemia can produce myocyte necrosis.","B":"Infarction occurs only when heart rate is very slow.","C":"Angina requires complete coronary artery rupture.","D":"Angina permanently destroys the affected myocardium."},"answer":"A","why":"Prolonged severe ischaemia can cause irreversible myocardial cell death; transient angina does not necessarily cause necrosis.","not":{"B":"Infarction can occur across a range of heart rates.","C":"Stable angina may result from fixed stenosis without rupture.","D":"Transient angina ordinarily reflects reversible myocardial ischaemia."}},{"id":"lt-lecture-6:7e913e00","chapter":"pulmonary","section":"1-two-circulations-in-one-lung","type":"anatomy","stem":"Which pair correctly identifies the lung's respiratory and supporting arterial circulations?","options":{"A":"Bronchial arteries for gas exchange and coronary arteries for support.","B":"Pulmonary arteries for support and hepatic arteries for gas exchange.","C":"Pulmonary arteries: gas exchange; bronchial arteries: support.","D":"Pulmonary veins for gas exchange and aortic veins for support."},"answer":"C","why":"Pulmonary arteries carry blood for gas exchange, while bronchial arteries from the aorta nourish lung supporting structures.","not":{"A":"Bronchial arteries primarily nourish lung tissue; coronary arteries nourish heart.","B":"The functional roles of pulmonary and bronchial supplies are reversed.","D":"Pulmonary veins return oxygenated blood; aortic veins are not a normal supply."}},{"id":"lt-lecture-6:8ea936cc","chapter":"pulmonary","section":"1-two-circulations-in-one-lung","type":"mechanism","stem":"Why can some bronchial venous drainage slightly lower oxygen content of blood reaching the left atrium?","options":{"A":"Bronchial venous blood drains only into the superior vena cava.","B":"Some bronchial venous blood joins pulmonary veins.","C":"Bronchial arteries arise directly from right ventricle.","D":"Pulmonary arterial blood bypasses alveolar capillaries entirely."},"answer":"B","why":"Some bronchial venous return enters pulmonary veins, mixing a small amount of deoxygenated blood with oxygenated pulmonary venous blood.","not":{"A":"Not all bronchial venous blood returns only through systemic veins.","C":"Bronchial arteries arise from the systemic arterial circulation.","D":"Normal pulmonary blood passes through alveolar capillary networks."}},{"id":"lt-lecture-6:dcbf5453","chapter":"pulmonary","section":"2-same-flow-much-lower-pressure","type":"mechanism","stem":"During exercise, pulmonary blood flow increases markedly with relatively little rise in pulmonary artery pressure. Why?","options":{"A":"Pulmonary arterioles uniformly constrict during exercise.","B":"All pulmonary capillaries close to maintain pressure.","C":"Pulmonary veins increase resistance to prevent overfilling.","D":"Recruitment and distension lower vascular resistance."},"answer":"D","why":"Recruiting previously underperfused capillaries and distending open vessels accommodates higher flow while limiting the pressure increase.","not":{"A":"Constricting arterioles would tend to increase pressure for a given flow.","B":"Closing capillaries would reduce the available vascular bed.","C":"Increased venous resistance would impede drainage and raise upstream pressure."}},{"id":"lt-lecture-6:42f3eaec","chapter":"pulmonary","section":"3-why-the-alveoli-stay-dry","type":"mechanism","stem":"Which pressure relationship helps prevent fluid accumulation in normal pulmonary alveoli?","options":{"A":"Relatively low pulmonary capillary hydrostatic pressure.","B":"Pulmonary capillary pressure consistently exceeds systemic arterial pressure.","C":"Absence of plasma proteins in pulmonary capillaries.","D":"Higher alveolar protein pressure than in capillary plasma."},"answer":"A","why":"Low pulmonary capillary hydrostatic pressure relative to plasma oncotic forces helps minimise filtration into air spaces.","not":{"B":"Pulmonary capillary pressure is much lower than systemic arterial pressure.","C":"Plasma proteins contribute the inward oncotic force.","D":"Alveolar spaces normally contain little free fluid and protein."}},{"id":"lt-lecture-6:661bcb50","chapter":"pulmonary","section":"4-gravity-posture-and-the-lung-s-blood-reservoir","type":"data-interpretation","stem":"A person lies down after standing upright. What happens to pulmonary blood volume in the lecture's illustration?","options":{"A":"It falls by approximately 400 mL.","B":"It remains fixed regardless of posture.","C":"It rises by approximately 400 mL.","D":"It falls until alveolar flow stops."},"answer":"C","why":"Supine positioning redistributes blood centrally, increasing the pulmonary blood reservoir by about 400 mL in the lecture.","not":{"A":"The lecture describes an increase, not decrease, on lying down.","B":"Pulmonary blood volume varies with posture.","D":"Blood flow does not normally stop merely because someone lies down."}},{"id":"lt-lecture-6:23d8dbf7","chapter":"pulmonary","section":"4-gravity-posture-and-the-lung-s-blood-reservoir","type":"application","stem":"Why can lying flat aggravate breathlessness in left ventricular failure?","options":{"A":"It sharply lowers the volume returning from the legs.","B":"Increased central blood volume raises pulmonary venous pressure.","C":"It directly destroys red cells within the pulmonary capillaries.","D":"Pulmonary circulation becomes independent of the left atrium."},"answer":"B","why":"A supine fluid shift increases thoracic blood volume; a failing left ventricle cannot clear the extra return, promoting pulmonary congestion.","not":{"A":"Venous return from dependent veins generally increases when supine.","C":"Red-cell destruction does not explain orthopnoea.","D":"Left atrial and pulmonary venous pressures remain tightly related."}},{"id":"lt-lecture-6:05fc9a35","chapter":"pulmonary","section":"5-low-oxygen-constricts-lung-vessels","type":"mechanism","stem":"An alveolar region becomes poorly ventilated and its oxygen tension falls. What local pulmonary vascular response occurs?","options":{"A":"Arteriolar dilation, drawing more blood to the region.","B":"Systemic venous constriction, increasing cardiac preload.","C":"Complete loss of autonomic input to the region.","D":"Pulmonary arterioles constrict, redirecting blood."},"answer":"D","why":"Low alveolar oxygen causes hypoxic pulmonary vasoconstriction, redirecting flow toward regions with better ventilation.","not":{"A":"Pulmonary hypoxic regulation is opposite to the usual local systemic response.","B":"Systemic venoconstriction is not the direct regional lung response.","C":"The response is local vascular contraction rather than loss of innervation."}},{"id":"lt-lecture-6:28fa99f6","chapter":"pulmonary","section":"5-low-oxygen-constricts-lung-vessels","type":"mechanism","stem":"Why can chronic widespread alveolar hypoxia lead to pulmonary hypertension?","options":{"A":"Persistent hypoxic constriction increases lung resistance.","B":"Persistent hypoxia opens every pulmonary capillary without resistance.","C":"Widespread hypoxia lowers pulmonary vascular smooth-muscle tone.","D":"Chronic hypoxia eliminates blood passing through the lungs."},"answer":"A","why":"When hypoxic constriction affects much of the lung, cumulative resistance rises and pulmonary arterial pressure can increase.","not":{"B":"Recruitment is a different response that lowers resistance.","C":"The lecture explicitly associates hypoxia with pulmonary vasoconstriction.","D":"Lung flow generally continues but faces increased resistance."}},{"id":"lt-lecture-6:e8efa5e3","chapter":"pulmonary","section":"5-low-oxygen-constricts-lung-vessels","type":"comparison","stem":"How does local hypoxia affect most systemic arterioles versus pulmonary arterioles?","options":{"A":"Both primarily constrict to lower oxygen delivery.","B":"Systemic vessels constrict while pulmonary vessels dilate.","C":"Systemic vessels dilate; pulmonary vessels constrict.","D":"Both remain relatively insensitive to tissue oxygen."},"answer":"C","why":"Systemic hypoxic tissues commonly dilate to improve supply, whereas low alveolar oxygen constricts adjacent pulmonary arterioles to improve ventilation–perfusion matching.","not":{"A":"Systemic tissues usually need increased flow in hypoxia.","B":"The response directions have been reversed.","D":"Oxygen tension influences both beds, but their dominant local responses differ."}},{"id":"lt-lecture-6:cc7a0b8e","chapter":"splanchnic","section":"1-an-unusual-route-through-two-capillary-beds","type":"anatomy","stem":"Which arterial set forms the principal splanchnic supply to abdominal digestive organs?","options":{"A":"Coronary, internal carotid and renal arteries.","B":"Coeliac and both mesenteric arteries.","C":"Subclavian, vertebral and intercostal arteries.","D":"Pulmonary trunk, bronchial and phrenic arteries."},"answer":"B","why":"The abdominal viscera receive main arterial inflow from the coeliac trunk and superior and inferior mesenteric arteries.","not":{"A":"These arteries supply heart, brain and kidney, not the digestive organs as a group.","C":"Those vessels chiefly serve upper body and thoracic regions.","D":"Pulmonary and bronchial arteries do not provide the main abdominal visceral supply."}},{"id":"lt-lecture-6:182b9713","chapter":"splanchnic","section":"1-an-unusual-route-through-two-capillary-beds","type":"mechanism","stem":"Blood from intestinal capillaries normally reaches which additional capillary bed before returning to the heart?","options":{"A":"Brain capillaries via the internal carotid artery.","B":"Pulmonary capillaries through the inferior vena cava.","C":"Coronary capillaries through the aortic sinus.","D":"Hepatic sinusoids through the portal vein."},"answer":"D","why":"Intestinal venous blood enters the hepatic portal system and passes through liver sinusoids before reaching systemic veins.","not":{"A":"Gut blood does not normally route through the carotid artery.","B":"Inferior vena cava blood reaches the right heart before lung capillaries.","C":"Coronary capillaries arise from systemic arteries, not portal drainage."}},{"id":"lt-lecture-6:cdce63ee","chapter":"splanchnic","section":"2-the-liver-s-double-blood-supply-and-its-zones","type":"mechanism","stem":"Which liver inflow delivers nutrient-rich blood collected from the gut?","options":{"A":"The portal vein.","B":"The hepatic vein.","C":"The pulmonary vein.","D":"The inferior vena cava."},"answer":"A","why":"The portal vein carries absorbed nutrients and venous blood from digestive organs into hepatic sinusoids.","not":{"B":"Hepatic veins drain liver blood toward the inferior vena cava.","C":"Pulmonary veins carry oxygenated blood to the left atrium.","D":"The inferior vena cava receives hepatic venous drainage rather than delivering gut blood directly to sinusoids."}},{"id":"lt-lecture-6:a4f7301a","chapter":"splanchnic","section":"2-the-liver-s-double-blood-supply-and-its-zones","type":"application","stem":"During severe hepatic hypoperfusion, cells near the central vein are especially vulnerable to hypoxia. Why?","options":{"A":"They are closest to arterial inflow.","B":"They receive blood with the highest oxygen content.","C":"They are farthest downstream from the portal triads.","D":"They are located outside the hepatic sinusoidal network."},"answer":"C","why":"Centrilobular cells receive blood after it has travelled from portal triads, making them less oxygenated and vulnerable.","not":{"A":"Oxygenated hepatic arterial inflow enters near the portal triads.","B":"Blood oxygen content generally falls as it traverses sinusoids.","D":"Centrilobular hepatocytes remain within the sinusoidal perfusion system."}},{"id":"lt-lecture-6:bf61a192","chapter":"splanchnic","section":"3-blood-flow-after-meals-and-in-shock","type":"mechanism","stem":"Following a substantial meal, intestinal blood flow rises for several hours. What primarily drives this response?","options":{"A":"Reduced intestinal metabolism during nutrient absorption.","B":"Local metabolic activity and absorptive demand.","C":"Global sympathetic constriction of intestinal arteries.","D":"Complete diversion of portal blood away from liver."},"answer":"B","why":"Postprandial metabolic and absorptive activity promotes local gastrointestinal hyperaemia; the lecture notes it can last about three hours.","not":{"A":"Absorption increases rather than abolishes local work.","C":"Sympathetic constriction usually opposes the flow increase.","D":"Portal flow continues to deliver absorbed substances to liver."}},{"id":"lt-lecture-6:41387e70","chapter":"splanchnic","section":"3-blood-flow-after-meals-and-in-shock","type":"application","stem":"In severe haemorrhagic shock, why does sympathetic constriction of splanchnic vessels help initially?","options":{"A":"It increases flow to the intestinal mucosa above baseline.","B":"It increases hepatic oxygen extraction to 100%.","C":"It prevents all intestinal ischaemia during shock.","D":"It redistributes flow and mobilises stored venous blood."},"answer":"D","why":"The splanchnic bed is a large blood reservoir; vasoconstriction redirects perfusion and recruits stored blood toward central circulation.","not":{"A":"Mucosal flow may decrease, risking ischaemia.","B":"Extraction is not necessarily complete.","C":"Severe or prolonged constriction can contribute to intestinal injury."}},{"id":"lt-lecture-6:aca8db0b","chapter":"splanchnic","section":"4-why-does-fluid-collect-as-ascites","type":"mechanism","stem":"Portal hypertension promotes ascites partly by increasing which force?","options":{"A":"Hydrostatic pressure in hepatic sinusoids.","B":"Plasma oncotic pressure within hepatic capillaries.","C":"Arterial oxygen tension in the hepatic vein.","D":"Interstitial lymphatic pumping efficiency."},"answer":"A","why":"Higher sinusoidal hydrostatic pressure increases fluid filtration and hepatic lymph formation; excess can enter the peritoneal cavity.","not":{"B":"Higher plasma oncotic pressure would oppose outward fluid filtration.","C":"Oxygen tension is not the main Starling-force mechanism.","D":"Improved lymphatic clearance would tend to oppose accumulation."}},{"id":"lt-lecture-6:101d7225","chapter":"splanchnic","section":"4-why-does-fluid-collect-as-ascites","type":"conceptual","stem":"Why can the protein concentration of ascites vary between patients?","options":{"A":"All ascites is produced by red-cell destruction.","B":"Ascites contains exactly the same proteins as blood.","C":"Its mechanism and site of fluid formation differ.","D":"The abdominal cavity produces a fixed protein solution."},"answer":"C","why":"Although hepatic sinusoids are protein-permeable, ascites composition depends on its underlying cause and filtration pathway.","not":{"A":"Red-cell breakdown is not the universal cause.","B":"Protein concentration is not necessarily identical to plasma.","D":"Ascites is pathologic fluid accumulation from varying mechanisms."}},{"id":"lt-lecture-6:1c5a3666","chapter":"skin","section":"1-skin-blood-flow-is-mainly-about-heat-not-nutrition","type":"mechanism","stem":"What is the main purpose of wide changes in skin blood flow during heating or cooling?","options":{"A":"To alter the heart's intrinsic pacemaker rate.","B":"To adjust body heat gain and loss.","C":"To maintain constant oxygen uptake by skin cells.","D":"To equalise pulmonary and systemic arterial pressures."},"answer":"B","why":"Cutaneous vessels dilate to increase heat loss and constrict to conserve heat; flow can far exceed nutritional needs.","not":{"A":"Heart pacemaking is not the main thermoregulatory role of skin circulation.","C":"Skin metabolic demand is relatively modest compared with variation in perfusion.","D":"Pulmonary-systemic pressure equality is unrelated to thermoregulation."}},{"id":"lt-lecture-6:54e22f1f","chapter":"skin","section":"1-skin-blood-flow-is-mainly-about-heat-not-nutrition","type":"mechanism","stem":"What role do arteriovenous anastomoses serve in fingers and other exposed skin?","options":{"A":"They transfer blood directly into lymphatic capillaries.","B":"They prevent sympathetic regulation of skin perfusion.","C":"They permanently close when environmental temperature rises.","D":"They provide adjustable shunts for heat exchange."},"answer":"D","why":"AV anastomoses can vary cutaneous blood delivery and heat transfer according to thermoregulatory needs.","not":{"A":"They connect arteries and veins rather than blood to lymph.","B":"Skin shunts are under autonomic control.","C":"Their opening and closing vary with temperature regulation."}},{"id":"lt-lecture-6:e3609140","chapter":"skin","section":"2-skin-blood-flow-in-shock","type":"application","stem":"A patient in compensated haemorrhagic shock has cold, pale skin. Which mechanism accounts for this?","options":{"A":"Increased sympathetic cutaneous vasoconstriction.","B":"Loss of vasomotor drive causing widespread dilation.","C":"Increased skin capillary blood volume from vasodilation.","D":"Direct activation of warm-sensitive skin receptors."},"answer":"A","why":"Sympathetic constriction reduces skin flow to preserve perfusion for vital organs, producing pallor and coolness.","not":{"B":"Loss of sympathetic tone would usually warm and flush skin.","C":"Higher cutaneous blood volume tends to increase redness.","D":"The primary response is systemic compensation, not skin warming."}},{"id":"lt-lecture-6:2909f0e0","chapter":"skin","section":"3-the-triple-response-of-lewis","type":"comparison","stem":"A very light stroke briefly leaves a pale line on the skin. How is this reaction best classified?","options":{"A":"The wheal component of the triple response.","B":"The spread of an axon-reflex flare.","C":"A brief local vasoconstrictor response.","D":"The red line of local capillary dilation."},"answer":"C","why":"The lecture describes a transient white reaction due to constriction; it is distinct from the classical red–flare–wheal response.","not":{"A":"Wheal is raised local oedema from permeability.","B":"Flare is surrounding redness from arteriolar dilation.","D":"The red line is a separate vasodilator response."}},{"id":"lt-lecture-6:8544a2a0","chapter":"skin","section":"3-the-triple-response-of-lewis","type":"mechanism","stem":"A firm stroke of the skin produces a raised wheal. Which local microvascular change directly forms it?","options":{"A":"Reduced endothelial permeability.","B":"Increased vascular permeability and fluid escape.","C":"Increased haemoglobin production by the skin.","D":"Reduced interstitial fluid volume from reabsorption."},"answer":"B","why":"The wheal is local oedema produced by increased permeability of small vessels and postcapillary venules.","not":{"A":"Reduced permeability would limit fluid leakage.","C":"Haemoglobin production is unrelated to immediate wheal formation.","D":"Wheal formation involves increased, not reduced, interstitial fluid."}},{"id":"lt-lecture-6:1316e033","chapter":"skin","section":"3-the-triple-response-of-lewis","type":"mechanism","stem":"Redness spreads beyond a stroked patch of skin as the flare develops. What generates this spread?","options":{"A":"Central spinal reflex contraction of the skin muscles.","B":"Direct filtration through enlarged lymphatic vessels.","C":"Venous thrombosis in the surrounding tissue.","D":"Antidromic impulses in branches of a sensory axon."},"answer":"D","why":"The flare is an axon reflex: sensory-nerve branches release vasodilator neuropeptides in surrounding skin without a spinal reflex.","not":{"A":"A central synaptic reflex is not needed for the axon reflex.","B":"Lymphatic filtration does not produce this arteriolar flare.","C":"The surrounding redness is functional vasodilation, not thrombosis."}},{"id":"lt-lecture-6:e26e0e6d","chapter":"skin","section":"3-the-triple-response-of-lewis","type":"conceptual","stem":"Which sequence best describes the classical triple response of Lewis?","options":{"A":"Red line, flare and wheal.","B":"White line, pallor, skin cooling.","C":"Raised wheal, venous thrombosis, scar.","D":"Flare, complete blanching, no fluid leak."},"answer":"A","why":"The classical triple response consists of local redness, a spreading flare and an oedematous wheal.","not":{"B":"A white line is a separate lighter-stroke reaction.","C":"Thrombosis and scar are not normal features.","D":"Wheal formation requires local fluid leak rather than none."}},{"id":"lt-lecture-6:68b2dadc","chapter":"fetal","section":"1-why-does-the-fetus-need-shortcuts","type":"mechanism","stem":"Why does the fetal cardiovascular system divert much blood away from the pulmonary circuit before birth?","options":{"A":"Pulmonary vascular resistance is exceptionally low before birth.","B":"The placenta oxygenates blood; fetal lungs resist flow.","C":"The fetal left ventricle cannot generate arterial pressure.","D":"Umbilical arteries carry already oxygenated blood to the heart."},"answer":"B","why":"The placenta performs gas exchange before birth; fluid-filled fetal lungs have high resistance, favouring right-to-left shunts.","not":{"A":"Pulmonary resistance is high before aeration.","C":"The fetal left ventricle contributes significantly to systemic output.","D":"Umbilical arteries carry relatively deoxygenated blood toward placenta."}},{"id":"lt-lecture-6:bc616fb8","chapter":"fetal","section":"2-trace-the-fetal-circuit","type":"anatomy","stem":"Which fetal vessel carries the most oxygenated blood from the placenta toward the fetus?","options":{"A":"An umbilical artery.","B":"The ductus arteriosus.","C":"The umbilical vein.","D":"The superior vena cava."},"answer":"C","why":"The umbilical vein returns oxygenated placental blood to the fetus; umbilical arteries return blood to placenta.","not":{"A":"Umbilical arteries carry fetal blood toward the placenta.","B":"The ductus arteriosus joins pulmonary trunk to aorta.","D":"The superior vena cava carries relatively less-oxygenated blood from the upper body."}},{"id":"lt-lecture-6:1bc5df7b","chapter":"fetal","section":"2-trace-the-fetal-circuit","type":"mechanism","stem":"What does the ductus venosus chiefly allow fetal blood to bypass?","options":{"A":"Much of the hepatic sinusoidal bed.","B":"The aortic arch and systemic arteries.","C":"The right atrium and vena cava.","D":"The placental exchange surface."},"answer":"A","why":"The ductus venosus routes much umbilical venous blood toward the inferior vena cava without traversing the full hepatic sinusoidal bed.","not":{"B":"Aortic systemic flow remains part of the fetal pathway.","C":"The shunt feeds blood into the vena cava and heart.","D":"Placental exchange occurs before umbilical venous return."}},{"id":"lt-lecture-6:16752946","chapter":"fetal","section":"2-trace-the-fetal-circuit","type":"mechanism","stem":"Which fetal opening directs oxygen-rich right atrial blood toward the left atrium?","options":{"A":"The ductus venosus.","B":"The ductus arteriosus.","C":"The foramen of Monro.","D":"The foramen ovale."},"answer":"D","why":"The foramen ovale provides a right-to-left atrial shunt that helps deliver relatively well-oxygenated blood to upper-body organs.","not":{"A":"The ductus venosus shunts across liver circulation.","B":"The ductus arteriosus links pulmonary artery and aorta.","C":"The foramen of Monro is a CSF ventricular passage."}},{"id":"lt-lecture-6:0ec90f69","chapter":"fetal","section":"2-trace-the-fetal-circuit","type":"mechanism","stem":"Where does the ductus arteriosus carry much fetal right ventricular output?","options":{"A":"Directly from right atrium to left atrium.","B":"From pulmonary trunk into descending aorta.","C":"From left ventricle into hepatic portal vein.","D":"From umbilical vein into inferior vena cava."},"answer":"B","why":"High prenatal pulmonary resistance diverts much right ventricular output through ductus arteriosus into the aorta.","not":{"A":"Right-to-left atrial passage occurs at the foramen ovale.","C":"Left ventricular output does not enter the portal vein.","D":"Umbilical venous diversion occurs at the ductus venosus."}},{"id":"lt-lecture-6:0d50c615","chapter":"fetal","section":"3-fetal-haemoglobin-grabbing-oxygen-from-the-mother","type":"mechanism","stem":"Why does fetal haemoglobin load oxygen effectively at the placental interface?","options":{"A":"It binds 2,3-BPG more tightly than adult haemoglobin.","B":"Its iron permanently binds each oxygen molecule.","C":"Its weaker 2,3-BPG binding increases oxygen affinity.","D":"It is produced without haem groups before birth."},"answer":"C","why":"HbF interacts less with 2,3-BPG, shifting its oxygen dissociation curve left and favouring oxygen uptake from maternal blood.","not":{"A":"Stronger 2,3-BPG binding would lower oxygen affinity.","B":"Oxygen binding is reversible, not permanent.","D":"Fetal haemoglobin still contains iron-bearing haem groups."}},{"id":"lt-lecture-6:4c647e8f","chapter":"fetal","section":"4-what-closes-after-delivery","type":"mechanism","stem":"Immediately after the first effective breaths, what happens to pulmonary vascular resistance?","options":{"A":"It falls as the lungs expand and oxygen tension rises.","B":"It rises because alveolar oxygen stimulates constriction.","C":"It remains unchanged until umbilical vessels close.","D":"It equals systemic resistance because both circuits merge."},"answer":"A","why":"Lung aeration and increased alveolar oxygen rapidly lower pulmonary vascular resistance, increasing pulmonary blood flow.","not":{"B":"Alveolar oxygen generally relieves pulmonary hypoxic vasoconstriction.","C":"Pulmonary adaptation begins with the first breaths.","D":"Pulmonary and systemic circuits retain very different resistance values."}},{"id":"lt-lecture-6:5cbb586b","chapter":"fetal","section":"4-what-closes-after-delivery","type":"mechanism","stem":"After cord clamping and lung aeration, what pressure change favours functional closure of the foramen ovale?","options":{"A":"Right atrial pressure rises above left atrial pressure.","B":"Pulmonary resistance remains very high.","C":"Umbilical venous inflow increases right atrial pressure.","D":"Left atrial pressure exceeds right atrial pressure."},"answer":"D","why":"Increased pulmonary venous return elevates left atrial pressure while loss of placental venous return reduces right-sided filling, pressing the flap closed.","not":{"A":"Right atrial dominance normally supports fetal shunting, not closure.","B":"Pulmonary resistance falls with first breaths.","C":"Clamping removes rather than increases umbilical venous return."}},{"id":"lt-lecture-6:43b3b471","chapter":"fetal","section":"4-what-closes-after-delivery","type":"anatomy","stem":"What is the fibrous adult remnant of the ductus arteriosus?","options":{"A":"The fossa ovalis.","B":"Ligamentum arteriosum.","C":"Ligamentum venosum.","D":"Ligamentum teres hepatis."},"answer":"B","why":"The ductus arteriosus normally closes after birth and becomes the ligamentum arteriosum. This remnant is distinct from the foramen ovale and ductus venosus remnants.","not":{"A":"The foramen ovale becomes the fossa ovalis.","C":"The ductus venosus becomes ligamentum venosum.","D":"The left umbilical vein becomes ligamentum teres hepatis."}},{"id":"lt-lecture-6:f03e662d","chapter":"fetal","section":"4-what-closes-after-delivery","type":"anatomy","stem":"Which adult remnant arises from closure of the umbilical vein?","options":{"A":"The fossa ovalis in the atrial septum.","B":"The ligamentum arteriosum.","C":"The ligamentum teres hepatis.","D":"The median umbilical ligament."},"answer":"C","why":"The umbilical vein closes to form the ligamentum teres hepatis of the liver. This structure is also associated with the falciform ligament of the adult liver.","not":{"A":"Fossa ovalis derives from the atrial septal foramen ovale.","B":"Ligamentum arteriosum derives from ductus arteriosus.","D":"The median umbilical ligament is an urachal remnant."}}]};
